// Tree-walking interpreter for a tiny expression language
// Supports: number literals, variables, binary operators (+,-,*,/)

class Interpreter {
  constructor() {
    this.env = {}; // variable store — maps name -> value
  }

  eval(node) {
    switch (node.type) {
      case 'Literal':
        return node.value;

      case 'Identifier':
        if (!(node.name in this.env))
          throw new ReferenceError(`Undefined variable: ${node.name}`);
        return this.env[node.name];

      case 'BinaryExpression': {
        const left  = this.eval(node.left);   // recursive!
        const right = this.eval(node.right);  // recursive!
        switch (node.operator) {
          case '+': return left + right;
          case '-': return left - right;
          case '*': return left * right;
          case '/':
            if (right === 0) throw new Error('Division by zero');
            return left / right;
          default:  throw new Error(`Unknown operator: ${node.operator}`);
        }
      }

      case 'VariableDeclaration':
        this.env[node.name] = this.eval(node.init);
        return undefined;

      case 'Program':
        let result;
        for (const stmt of node.body) result = this.eval(stmt);
        return result;

      default:
        throw new Error(`Unknown node type: ${node.type}`);
    }
  }
}

// The AST for:  let area = 6 * 7
const program = {
  type: 'Program',
  body: [
    {
      type: 'VariableDeclaration',
      name: 'area',
      init: {
        type: 'BinaryExpression',
        operator: '*',
        left:  { type: 'Literal', value: 6 },
        right: { type: 'Literal', value: 7 }
      }
    },
    { type: 'Identifier', name: 'area' }
  ]
};

const interp = new Interpreter();
console.log(interp.eval(program)); // 42
console.log(interp.env);           // { area: 42 }

// If this were inside a loop that ran 100,000 times,
// the interpreter would walk the BinaryExpression nodes
// 100,000 times — the same pointer traversal every iteration.

// PART 1: Compile an AST expression to stack-machine bytecode
function compileToBytecode(node) {
  const instructions = [];

  function emit(op, arg) {
    instructions.push(arg !== undefined ? { op, arg } : { op });
  }

  function compile(n) {
    switch (n.type) {
      case 'Literal':
        emit('PUSH', n.value);
        break;
      case 'Identifier':
        emit('LOAD', n.name);
        break;
      case 'BinaryExpression':
        compile(n.left);   // left value ends up on stack
        compile(n.right);  // right value ends up on stack
        // now MUL/ADD/SUB pops both and pushes result
        emit(n.operator === '+' ? 'ADD' :
             n.operator === '-' ? 'SUB' :
             n.operator === '*' ? 'MUL' : 'DIV');
        break;
      case 'VariableDeclaration':
        compile(n.init);
        emit('STORE', n.name); // pop top of stack -> env[name]
        break;
      case 'Program':
        for (const stmt of n.body) compile(stmt);
        break;
      default:
        throw new Error(`Cannot compile node: ${n.type}`);
    }
  }

  compile(node);
  return instructions;
}

// PART 2: Stack VM — execute bytecode
function runVM(instructions, env = {}) {
  const stack = [];
  for (const { op, arg } of instructions) {
    switch (op) {
      case 'PUSH':  stack.push(arg); break;
      case 'LOAD':  stack.push(env[arg]); break;
      case 'STORE': env[arg] = stack.pop(); break;
      case 'ADD': { const b = stack.pop(), a = stack.pop(); stack.push(a + b); break; }
      case 'SUB': { const b = stack.pop(), a = stack.pop(); stack.push(a - b); break; }
      case 'MUL': { const b = stack.pop(), a = stack.pop(); stack.push(a * b); break; }
      case 'DIV': { const b = stack.pop(), a = stack.pop(); stack.push(a / b); break; }
      default: throw new Error(`Unknown opcode: ${op}`);
    }
  }
  return { result: stack[0], env };
}

// Test: compile and run  let area = 6 * 7
const ast = {
  type: 'Program',
  body: [
    { type: 'VariableDeclaration', name: 'area',
      init: { type: 'BinaryExpression', operator: '*',
              left:  { type: 'Literal', value: 6 },
              right: { type: 'Literal', value: 7 } } },
    { type: 'Identifier', name: 'area' }
  ]
};

const bytecode = compileToBytecode(ast);
console.log('bytecode:', bytecode);
// [
//   { op: 'PUSH', arg: 6 },
//   { op: 'PUSH', arg: 7 },
//   { op: 'MUL' },
//   { op: 'STORE', arg: 'area' },
//   { op: 'LOAD', arg: 'area' }
// ]

const { result, env } = runVM(bytecode);
console.log('result:', result); // 42
console.log('env:', env);       // { area: 42 }

// Key insight: if this code ran 10,000 times,
// we only compile ONCE, then run the flat array 10,000 times.
// No pointer chasing, no recursive dispatch, no switch on node.type.
